// MOS 6502 full-ISA testbench.
//
// Two modes:
//   default    — ISS vector replay: loads work/sim/mem.hex, runs from reset,
//                and compares (pc, a, x, y, p, s) at every opcode-fetch
//                boundary against work/sim/vectors.hex (generated by
//                scripts/make_isa_vectors.py from the vendored py65
//                oracle); final memory compared against gold_mem.hex.
//   +klaus     — loads references/6502_functional_test.bin.hex and
//                free-runs; success = the self-loop trap at $3469 (the
//                standard bin_files build's success jmp *), detected as
//                three consecutive fetches of the same PC.
`timescale 1ns/1ps

module tb_top;

    localparam int TCK = 100;
    localparam int MAXVEC = 20000;

    logic clk = 1'b0;
    always #(TCK/2) clk = ~clk;

    logic        rst_n;
    wire  [15:0] bus_addr;
    wire  [7:0]  bus_data_o;
    logic [7:0]  bus_data_i;
    wire         bus_we;
    logic        irq_n = 1'b1;
    logic        nmi_n = 1'b1;
    wire         fetch_o, fault_o;
    wire  [15:0] pc_o;
    wire  [7:0]  status_o, a_o, x_o, y_o, s_o;

    mos_6502 dut (
        .clk, .rst_n, .bus_addr, .bus_data_i, .bus_data_o, .bus_we,
        .irq_n, .nmi_n, .fetch_o, .fault_o,
        .pc_o, .status_o, .a_o, .x_o, .y_o, .s_o
    );

    // ------------------------------------------------------------------
    // Memory
    // ------------------------------------------------------------------
    logic [7:0] mem  [0:65535];
    logic [7:0] gold [0:65535];
    logic       klaus;

    always_comb begin
        bus_data_i = mem[bus_addr];
    end
    always_ff @(posedge clk) begin
        if (bus_we) mem[bus_addr] <= bus_data_o;
    end

    // ------------------------------------------------------------------
    // Vector file
    // ------------------------------------------------------------------
    logic [15:0] vec [0:6*MAXVEC];
    int          nvec;
    int          vidx;
    int          checks = 0;
    int          errors = 0;
    logic [15:0] last_fetch_pc;
    int          same_fetch;
    longint      cycles = 0;
    logic [15:0] irq_window_a [0:0];
    logic [15:0] irq_handler_a [0:0];
    logic [15:0] nvec_a [0:0];
    logic [15:0] nmi_window_a [0:0];
    logic [15:0] irq_window;
    logic [15:0] irq_handler;
    logic [15:0] nmi_window;

    logic [15:0] hist [0:7];
    int hi = 0;
    always @(posedge clk) if (rst_n && dut.state == dut.S_FETCH) begin
        hist[hi] <= pc_o;
        hi       <= (hi + 1) & 7;
    end
    task automatic fail(input string what);
        errors++;
        if (errors == 1) begin
            for (int k = 0; k < 8; k++)
                $display("HIST[%0d] %04x", (hi + k) & 7, hist[(hi + k) & 7]);
            $display("VEC neighborhood:");
            for (int k = vidx - 3; k <= vidx + 2; k++)
                if (k >= 0 && k < nvec)
                    $display("VEC[%0d] %04x %h %h %h %h %h",
                             k, vec[k*6+0], vec[k*6+1], vec[k*6+2],
                             vec[k*6+3], vec[k*6+4], vec[k*6+5]);
        end
        if (errors <= 20)
            $display("CHECK FAILED [%s] vidx=%0d at %0t: op=%02x pc=%04x a=%02x x=%02x y=%02x p=%02x s=%02x (expected %04x %02x %02x %02x %02x %02x)",
                     what, vidx, $time, dut.opcode, pc_o, a_o, x_o, y_o, status_o, s_o,
                     vec[vidx*6+0], vec[vidx*6+1], vec[vidx*6+2],
                     vec[vidx*6+3], vec[vidx*6+4], vec[vidx*6+5]);
    endtask

    initial begin
        klaus = $test$plusargs("klaus");
        vidx = 0;
        same_fetch = 0;
        for (int i = 0; i < 65536; i++) begin
            mem[i] = 8'h00;
            gold[i] = 8'h00;
        end
        for (int i = 0; i < 6*MAXVEC; i++) vec[i] = 16'hxxxx;
        if (klaus) begin
            $readmemh("references/6502_functional_test.bin.hex", mem);
            // the bin_files distribution leaves the vectors to the harness:
            // standard entry is $0400
            mem[16'hFFFC] = 8'h00;
            mem[16'hFFFD] = 8'h04;
        end else begin
            $readmemh("work/sim/mem.hex", mem);
            $readmemh("work/sim/vectors.hex", vec);
            $readmemh("work/sim/gold_mem.hex", gold);
            $readmemh("work/sim/nvec.hex", nvec_a);
            nvec = 32'(nvec_a[0]);
            irq_window = 16'hxxxx;
            irq_handler = 16'hxxxx;
            $readmemh("work/sim/window.hex", irq_window_a);
            $readmemh("work/sim/handler.hex", irq_handler_a);
            irq_window = irq_window_a[0];
            irq_handler = irq_handler_a[0];
            $readmemh("work/sim/nmiwin.hex", nmi_window_a);
            nmi_window = nmi_window_a[0];
        end
        rst_n = 1'b0;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst_n = 1'b1;
    end

    // forced-IRQ/NMI control mirroring the generator's rule: the IRQ asserts
    // once at the window and deasserts at the handler entry (post-RTI I=0
    // would re-take it); the NMI is a one-cycle low pulse (the core latches
    // the edge), fired once at the NMI window.
    bit irq_done = 0;
    bit nmi_done = 0;
    always @(negedge clk) begin
        if (!klaus && rst_n) begin
            if (!irq_done && pc_o == irq_window) begin
                irq_n = 1'b0;
                irq_done = 1'b1;
            end
            if (pc_o == irq_handler) irq_n = 1'b1;
            if (!nmi_done && pc_o == nmi_window - 1) begin
                nmi_n = 1'b0;
                nmi_done = 1'b1;
            end else if (nmi_done && nmi_n == 1'b0) begin
                nmi_n = 1'b1;
            end
        end
    end

    // Checker: at each fetch boundary compare against the next vector
    always @(posedge clk) begin
        if (rst_n && dut.state == dut.S_FETCH && !klaus) begin
            if (vidx < nvec) begin
                if (pc_o !== vec[vidx*6+0] || a_o !== vec[vidx*6+1][7:0]
                    || x_o !== vec[vidx*6+2][7:0] || y_o !== vec[vidx*6+3][7:0]
                    || status_o !== vec[vidx*6+4][7:0]
                    || s_o !== vec[vidx*6+5][7:0]) begin
                    fail("vector");
                end else begin
                    checks++;
                end
                vidx++;
            end
        end
    end

    // Watchers: fault detection, Klaus self-loop detection
    always @(posedge clk) begin
        if (rst_n) begin
            cycles++;
            if (fault_o) begin
                errors++;
                if (errors <= 20)
                    $display("FAULT at %04x (op %02x) at %0t", pc_o, dut.opcode, $time);
            end
            if (klaus) begin
                // sample only on opcode fetches: a self-loop trap re-fetches
                // the same pc, but operand cycles in between must not reset
                // the counter
                if (dut.state == dut.S_FETCH) begin
                    if (pc_o == last_fetch_pc) begin
                        same_fetch++;
                        if (same_fetch == 2) begin
                            $display("Klaus trap at %04x after %0d cycles", pc_o, cycles);
                            if (pc_o == 16'h3469)
                                $display("Apple 6502 KLAUS TEST PASSED");
                            else
                                $display("Apple 6502 KLAUS TEST FAILED (trap %04x)", pc_o);
                            $finish;
                        end
                    end else begin
                        same_fetch = 0;
                        last_fetch_pc = pc_o;
                    end
                end
            end
        end
    end

    // Completion (vector mode): final memory compare
    initial begin
        if (!klaus) begin
            wait (vidx >= nvec);
            repeat (10) @(posedge clk);
            for (int i = 0; i < 65536; i++) begin
                if (mem[i] !== gold[i]) begin
                    errors++;
                    if (errors <= 20)
                        $display("MEM MISMATCH at %04x: dut=%02x gold=%02x", i, mem[i], gold[i]);
                end
            end
            checks += 65536;
            if (errors == 0)
                $display("Apple 6502 FULL ISA TEST PASSED checks=%0d vectors=%0d", checks, nvec);
            else
                $display("Apple 6502 FULL ISA TEST FAILED errors=%0d", errors);
            $finish;
        end
    end

    // Watchdog
    initial begin
        if (klaus) #20_000_000_000;
        else #100_000_000;
        $display("Apple 6502 TEST TIMEOUT (klaus=%0b pc=%04x)", klaus, pc_o);
        if (klaus) begin
            $display("timeout state=%0d fetch=%b same_fetch=%0d last_fetch_pc=%04x irq_n=%b nmi_n=%b p=%b",
                     dut.state, fetch_o, same_fetch, last_fetch_pc, irq_n, nmi_n, dut.p);
            for (int k = 0; k < 8; k++)
                $display("HIST[%0d] %04x", (hi + k) & 7, hist[(hi + k) & 7]);
        end
        $finish;
    end
endmodule
